_sage_const_4 = Integer(4); _sage_const_1 = Integer(1); _sage_const_3 = Integer(3); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_7 = Integer(7); _sage_const_6 = Integer(6); _sage_const_9 = Integer(9); _sage_const_5 = Integer(5)
def gram_schmidt_process(vectors):
    # Initialize list for orthogonal vectors u
    u_list = []

    for v in vectors:
        # Start ui as vi
        ui = v
        
        # Subtract projections of v onto all previous uj
        for uj in u_list:
            # Calculate coefficient μ = (v . uj) / ||uj||^2
            # Note: dot_product returns a scalar
            mu = v.dot_product(uj) / uj.dot_product(uj)
            
            # ui = ui - μ * uj
            ui = ui - mu * uj
            
        # Append the new orthogonal vector ui to the list
        # (Optional: Check if ui is zero to handle linearly dependent inputs)
        if not ui.is_zero():
            u_list.append(ui)
            
    return u_list

